+      <!-- 未连接 -->
+      <div v-if="!isConnected && !isSwitching">
+        <span style="margin-right: 10px;">自动连接中，点击选择：</span>
+        <el-select v-model="selectedPort" placeholder="请选择设备" size="small" style="width: 200px;">
