+        <el-button type="primary" size="small" :loading="isWorking" @click="connectDevice">连接</el-button>
+      </div>
+
+      <!-- 已连接 -->
+      <div v-else-if="isConnected && !isSwitching">
+        <span :style="{ color: 'green', marginRight: '10px' }">已连接设备 "{{ connectedPort }}"</span>
+        <el-button type="primary" size="small" @click="startSwitch">切换</el-button>
+      </div>
+
