+          <el-option
+            v-for="port in ports"
+            :key="port.path"
+            :label="port.friendlyName || port.path"
+            :value="port.path"
+          />
+        </el-select>
+        <el-button type="primary" size="small" :loading="isWorking" @click="confirmSwitch">确认</el-button>
+        <el-button size="small" @click="cancelSwitch">取消</el-button>
+      </div>
+
