+<script setup lang="ts">
+import Menu from './components/Menu.vue';
+import { version } from '../../package.json';
+import { ref, onMounted } from 'vue';
+import { ElMessage } from 'element-plus';
+
+const isConnected = ref(false);
+const isSwitching = ref(false);
+const isWorking = ref(false);
+
+const ports = ref<{ path: string; friendlyName?: string }[]>([]);
+const selectedPort = ref('');
+const connectedPort = ref('');
+
+// ----------------- 方法 -----------------
+const loadPorts = async () => {
+  try {
+    ports.value = await window.electronAPI.listPorts();
+  } catch (err) {
+    console.error('获取串口列表失败:', err);
+  }
+};
+
+const connectDevice = async () => {
+  if (!selectedPort.value) {
+    ElMessage.warning('请选择一个设备');
+    return;
+  }
+  isWorking.value = true;
+  try {
+    const success = await window.electronAPI.connectPort(selectedPort.value);
+    if (success) {
+      isConnected.value = true;
+      connectedPort.value = selectedPort.value;
+      ElMessage.success(`成功连接到 ${selectedPort.value}`);
+    } else {
+      ElMessage.error('连接失败');
+    }
+  } catch (err) {
+    console.error(err);
+    ElMessage.error('连接过程中出现错误');
+  } finally {
+    isWorking.value = false;
+  }
+};
+
+const startSwitch = () => {
+  isSwitching.value = true;
+};
+
+const confirmSwitch = async () => {
+  if (!selectedPort.value) {
+    ElMessage.warning('请选择一个设备');
+    return;
+  }
+  isWorking.value = true;
+  try {
+    const success = await window.electronAPI.connectPort(selectedPort.value);
+    if (success) {
+      connectedPort.value = selectedPort.value;
+      ElMessage.success(`已切换到 ${selectedPort.value}`);
+    } else {
+      ElMessage.error('切换失败');
+    }
+  } catch (err) {
+    console.error(err);
+    ElMessage.error('切换过程中出现错误');
+  } finally {
+    isWorking.value = false;
+    isSwitching.value = false;
+  }
+};
+
+const cancelSwitch = () => {
+  isSwitching.value = false;
+};
+
+// ----------------- 生命周期 -----------------
+onMounted(() => {
+  loadPorts();
+
+  // 自动连接
+  window.electronAPI.autoConnect().then((port) => {
+    if (port) {
+      isConnected.value = true;
+      connectedPort.value = port;
+    }
+  });
+
+  // 监听心跳
+  window.electronAPI.heartBeatStatusMessage((value) => {
+    isConnected.value = value;
+    if (!value) {
+      connectedPort.value = '';
+    }
+  });
+});
+</script>
+
